169	/* Map an MQTT status to the emoji_blob resource driving the shared animation,
170	 * or NULL to withdraw the Claude request (overlay released -> idle rotation).
171	 * Names must match g_emoji_names in emoji_blob.h. */
172	static const char *claude_emoji_name(const char *state)
173	{
174	    if (!strcmp(state, "executing")) return "claude-executing";
175	    if (!strcmp(state, "thinking"))  return "claude-thinking";
176	    if (!strcmp(state, "idle"))      return "claude-idle";
177	    return NULL;   /* "default" / offline: no agent animation */
