180	void claude_mqtt_poll(lv_timer_t *timer)
181	{
182	    static uint32_t lease;
183	    char state[16];
184	    bool changed;
185	    (void)timer;
186	    pthread_mutex_lock(&g_lock);
187	    changed = g_changed;
188	    if (changed) { strcpy(state, g_pending); strcpy(g_state, g_pending); g_changed = false; lease = lv_tick_get(); }
189	    else strcpy(state, g_state);
190	    pthread_mutex_unlock(&g_lock);
191	    if (changed || !strcmp(state, "default") || lv_tick_elaps(lease) < LEASE_SECONDS * 1000) {
192	        /* 通过 emoji_idle 仲裁接口投递 Agent 状态动画。CLAUDE 源优先级低于
193	         * VOICE:豆包 listen/speak 期间语音动画胜出,不会被状态动画抢占。 */
194	        emoji_idle_request(EMOJI_SRC_CLAUDE, claude_emoji_name(state));
195	        /* 手电筒开启时独占 LED,状态灯只更新 UI 不抢灯(否则会周期性熄灭手电筒)。 */
