            g_auto_emoji_pos = (g_auto_emoji_pos + 1) %
                (sizeof(g_auto_emoji_indices) / sizeof(g_auto_emoji_indices[0]));
            g_next_emoji = g_auto_emoji_indices[g_auto_emoji_pos];
