488	 * 否则手电筒点亮后会被状态灯周期性熄灭(表现为"亮一下就灭")。 */
489	extern bool g_flashlight_override;
490	
491	/*-----------------------------------------------------------------------
492	 * 语音意图:板载手电筒(WS2812 /dev/leds0)开关
493	 *
494	 * 从 ASR 识别原文里匹配 "手电筒/灯" + "打开/关闭",直接驱动板载 LED。
495	 * 运行在 session_loop(worker)线程:led_* 内部只是 open/write /dev/leds0
496	 * 的文件操作,线程安全;同步 g_led_is_on 供 UI 下次开窗回显,但不直接
497	 * 操作 light_switch 等 LVGL 控件(那不是线程安全的)。
498	 *
499	 * 返回 true 表示已命中并处理(命中后仍保留正常对话流,由豆包 TTS 口头
500	 * 确认);返回 false 表示非灯控意图,交给大模型正常应答。
501	 *---------------------------------------------------------------------*/
502	/* 空调红外学习去抖: two-pass ASR 会把"学习空调红外"重复回传十几帧,若每帧
503	 * 都起线程会并发读 /dev/lirc0、串口输出严重交织。用该标志保证只抓一次。 */
504	static volatile bool s_ac_learning = false;
505	
506	/* 红外学习进行中标志: 为真时 doubao_voice_start() 拒绝启动会话(挡住 face_detect
507	 * 等把音频拉回), 使采集窗口安静, 避免 CPU 抢占导致接收 FIFO 丢样。
508	 * 注: wakeup 线程原本也据此让出麦克风, 但该暂停已按需求暂时移除 —— 下次要
509	 * 学习红外时, 需在 wakeup.c 主循环重新加回 g_ir_learning 判空让麦, 否则唤醒
510	 * 麦克风采集的音频负载仍会污染抓帧。 */
511	volatile bool g_ir_learning = false;
512	
513	/* 本次学习输出的数组名: "学习开/关空调"分别抓开机帧/关机帧。仅在 s_ac_learning
514	 * 为真期间(单次学习)读写, 无并发。 */
515	static const char *s_ac_learn_label = "g_ac_frame_power_on";
516	
517	/* 空调红外抓帧线程:先停掉当前豆包会话并暂停唤醒,让系统安静下来再采集,
518	 * 否则并发音频负载会把每次采集都丢样毁掉(实测)。 */
519	static void *ac_ir_learn_thread(void *arg)
520	{
521	  (void)arg;
522	
523	  g_ir_learning = true;      /* 挡住会话重启(见 doubao_voice_start) */
524	  doubao_voice_stop();       /* 结束当前会话,释放音频/网络负载 */
525	  usleep(700 * 1000);        /* 等音频线程与 DMA 真正停下、FIFO 静默 */
526	
527	  ac_ir_learn_dump(s_ac_learn_label, 10000);
528	
529	  g_ir_learning = false;     /* 恢复 */
530	  s_ac_learning = false;
531	  return NULL;
532	}
533	
534	/* 空调开关状态,用于按状态翻转去抖(two-pass ASR 会重复回同一句)。
535	 * 初值 false 假设上电时空调为关;首条明确指令应为"打开空调"。 */
536	/* AC 指令时间去抖: two-pass ASR 会把同一句"打开空调"重复回传十几帧, 需去重;
537	 * 但不同次的命令(如没生效再喊一遍)必须允许重发。故按"同方向指令 N 毫秒内
538	 * 视为同一句而跳过"来去抖, 而非按开关状态(否则空调没真正开时再喊会被永久挡)。 */
