73	static void click_cb(lv_event_t *e)
74	{
75	    (void)e;
76	
77	    /* 当前叠层是否由某个状态源(Claude/语音)持有。状态叠层的 on_exit 为 NULL,
78	     * 且每 100ms 的状态轮询会重建它,需专门抑制;待机轮播则照旧走 on_exit。 */
79	    bool was_status = (g_status_shown[0] != '\0');
80	    emoji_idle_exit_cb_t on_exit = g_idle.on_exit;
