173	    lv_obj_set_pos(g_idle.overlay, 0, 0);
174	    lv_obj_set_style_bg_color(g_idle.overlay, lv_color_black(), 0);
175	    lv_obj_set_style_bg_opa(g_idle.overlay, LV_OPA_COVER, 0);
