177	    lv_obj_set_style_radius(g_idle.overlay, 0, 0);
178	    lv_obj_set_style_pad_all(g_idle.overlay, 0, 0);
179	    lv_obj_set_scrollbar_mode(g_idle.overlay, LV_SCROLLBAR_MODE_OFF);
180	    lv_obj_clear_flag(g_idle.overlay, LV_OBJ_FLAG_SCROLLABLE);
