184	    g_idle.img = lv_image_create(g_idle.overlay);
185	    lv_obj_set_size(g_idle.img, EMOJI_FRAME_W, EMOJI_FRAME_H);
186	    lv_obj_set_style_pad_all(g_idle.img, 0, 0);
187	    lv_obj_set_style_border_width(g_idle.img, 0, 0);
188	    lv_obj_align(g_idle.img, LV_ALIGN_CENTER, 0, 0);
189	    lv_image_set_src(g_idle.img, &g_dsc);
