192	    g_idle.timer = lv_timer_create(anim_cb, 300, NULL);
193	    lv_timer_set_repeat_count(g_idle.timer, -1);
194	    lv_obj_add_event_cb(g_idle.overlay, click_cb, LV_EVENT_CLICKED, NULL);
195	
196	    return g_idle.overlay;
197	}
