199	/*-----------------------------------------------------------------------
200	 * Status-source arbitration (priority: VOICE > CLAUDE)
201	 *---------------------------------------------------------------------*/
202	static void status_apply(void)
203	{
204	    const char *winner = NULL;
205	
206	    /* Highest enum value wins; first non-empty request from the top. */
207	    for (int s = EMOJI_SRC_COUNT - 1; s >= 0; s--) {
208	        if (g_src_name[s][0]) { winner = g_src_name[s]; break; }
209	    }
210	
211	    if (winner) {
212	        /* 用户已手动点掉状态叠层:只要仍是同一个状态就不重建,让用户停留在
213	         * 对话页;winner 变成别的状态(新交互/新状态)时解除抑制,恢复显示。 */
214	        if (g_status_dismissed) {
215	            if (strcmp(winner, g_dismissed_name) == 0) return;
216	            g_status_dismissed = false;
217	        }
218	        /* Re-assert when the winner changed, or when the overlay was
219	         * replaced out from under us: a status feed is live, so it keeps
220	         * reflecting state rather than staying gone. */
221	        if (strcmp(winner, g_status_shown) != 0 || !emoji_idle_is_active()) {
222	            if (emoji_idle_play(lv_scr_act(), winner, NULL)) {
223	                strncpy(g_status_shown, winner, EMOJI_NAME_MAX - 1);
224	                g_status_shown[EMOJI_NAME_MAX - 1] = '\0';
225	            }
226	        }
227	    } else if (g_status_shown[0] || g_status_dismissed) {
228	        /* No source wants the overlay: release it (and clear any dismiss
229	         * suppression) so the idle rotation (main.c) can take over again. */
230	        g_status_shown[0] = '\0';
231	        g_status_dismissed = false;
232	        emoji_idle_stop();
233	    }
234	}
235	
236	void emoji_idle_request(emoji_source_t src, const char *name)
237	{
238	    if ((unsigned)src >= EMOJI_SRC_COUNT) return;
239	
240	    if (name && name[0]) {
241	        strncpy(g_src_name[src], name, EMOJI_NAME_MAX - 1);
242	        g_src_name[src][EMOJI_NAME_MAX - 1] = '\0';
243	    } else {
244	        g_src_name[src][0] = '\0';
245	    }
246	    status_apply();
247	}
248	
249	bool emoji_idle_status_active(void)
250	{
251	    return g_status_shown[0] != '\0';
252	}
