import re,os,glob
REPO="/media/fenglei6/ssd1/VelaGoGoGo/contest2026_106_VelaGoGoGo"
sf=os.path.join(REPO,"app/home_scense/doubao/doubao_secret.h")
vals=set()
for line in open(sf,errors='replace'):
    for m in re.findall(r'"([^"]+)"',line):
        vals.add(m)
out=""
for jf in glob.glob(os.path.join(REPO,"logs/fenglei","**","*.jsonl"),recursive=True):
    out+=open(jf,errors='replace').read()
def mask(s):
    if len(s)<=2: return "*"*len(s)
    return s[0]+"*"*(len(s)-2)+s[-1]
print("所有引号值(掩码, 长度, 输出命中数):")
for v in sorted(vals,key=len):
    print("  len=%2d hits=%d  %s"%(len(v),out.count(v),mask(v)))
PY
echo "$MARK END rc=$?"
